def find_20th_smallest_sum():
    sums = set()

    # Since the 20th number is expected to be small (around 70), a limit of 1000 is very safe.
    limit = 1000 

    x = 1
    while True:
        y = x + 1
        while True:
            m = x*x + y*y

            if m > limit:
                break

            sums.add(m)
            y += 1

        # Optimization: If even the smallest possible sum involving x+1 exceeds the limit, we can stop early.
        if (x+1)**2 + (x+2)**2 > limit:
            break

        x += 1

    unique_sums = sorted(list(sums))

    if len(unique_sums) >= 20:
        return unique_sums[19] # 20th smallest is at index 19
    else:
        return f"Not enough unique sums found. Total found: {len(unique_sums)}"

print(find_20th_smallest_sum())
